const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry - Warburton Creek area (Australia)
  const warburtonCreek = ee.Geometry.Point(140.0, -27.0).buffer(5000); // 5km buffer

  // 2. Date ranges for 2025 (future - will likely have no data)
  const startDate = '2025-06-05';
  const endDate = '2025-07-05';
  const startDate2 = '2025-08-31';
  const endDate2 = '2025-09-30';

  // Function to get cloud-masked Sentinel-2 image
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to compute NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // Try Sentinel-2 for period 1 (June 2025)
  let s2_col1 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(warburtonCreek)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
    .map(maskS2clouds)
    .map(addNDVI);

  let s2_col2 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(warburtonCreek)
    .filterDate(startDate2, endDate2)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
    .map(maskS2clouds)
    .map(addNDVI);

  // Check collection sizes
  const size1 = s2_col1.size().getInfo();
  const size2 = s2_col2.size().getInfo();

  // If no Sentinel-2 data, try Landsat 8
  let col1, col2;
  if (size1 === 0 || size2 === 0) {
    console.log(`No Sentinel-2 data for 2025. Trying 2024...`);

    // Try 2024 instead
    const startDate2024 = '2024-06-05';
    const endDate2024 = '2024-07-05';
    const startDate22024 = '2024-08-31';
    const endDate22024 = '2024-09-30';

    // Landsat 8 cloud masking function
    function maskL8sr(image) {
      const qa = image.select('QA_PIXEL');
      const cloudMask = qa.bitwiseAnd(1 << 3).eq(0)
                         .and(qa.bitwiseAnd(1 << 4).eq(0));
      return image.updateMask(cloudMask);
    }

    // Landsat 8 NDVI: (B5 - B4) / (B5 + B4)
    function addLandsatNDVI(image) {
      const ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
      return image.addBands(ndvi);
    }

    col1 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(warburtonCreek)
      .filterDate(startDate2024, endDate2024)
      .map(maskL8sr)
      .map(addLandsatNDVI);

    col2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(warburtonCreek)
      .filterDate(startDate22024, endDate22024)
      .map(maskL8sr)
      .map(addLandsatNDVI);

    const size1_2024 = col1.size().getInfo();
    const size2_2024 = col2.size().getInfo();

    if (size1_2024 === 0 || size2_2024 === 0) {
      console.log(`Period 1 (Jun 2024) Images: ${size1_2024}`);
      console.log(`Period 2 (Sep 2024) Images: ${size2_2024}`);
      console.log(`<answer>C1</answer>`);
      return;
    }

    console.log(`Using Landsat 8 2024 data`);
    console.log(`Period 1 (Jun 2024) Images: ${size1_2024}`);
    console.log(`Period 2 (Sep 2024) Images: ${size2_2024}`);
  } else {
    col1 = s2_col1;
    col2 = s2_col2;
    console.log(`Using Sentinel-2 2025 data`);
    console.log(`Period 1 (Jun 2025) Images: ${size1}`);
    console.log(`Period 2 (Sep 2025) Images: ${size2}`);
  }

  // Create median composites
  const composite1 = col1.select('NDVI').median();
  const composite2 = col2.select('NDVI').median();

  // Count valid pixels
  const count1 = composite1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: warburtonCreek,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const count2 = composite2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: warburtonCreek,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (count1 === 0 || count2 === 0) {
    console.log(`Valid pixels - Period 1: ${count1}, Period 2: ${count2}`);
    console.log(`<answer>C2</answer>`);
    return;
  }

  // Calculate mean NDVI
  const ndvi1 = composite1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: warburtonCreek,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const ndvi2 = composite2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: warburtonCreek,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // Validate NDVI values
  if (ndvi1 === null || ndvi2 === null || 
      isNaN(ndvi1) || isNaN(ndvi2) ||
      ndvi1 < -1 || ndvi1 > 1 || 
      ndvi2 < -1 || ndvi2 > 1) {
    console.log(`Invalid NDVI values: ${ndvi1}, ${ndvi2}`);
    console.log(`<answer>C3</answer>`);
    return;
  }

  console.log(`Mean NDVI - Period 1: ${ndvi1.toFixed(4)}`);
  console.log(`Mean NDVI - Period 2: ${ndvi2.toFixed(4)}`);
  console.log(`Valid pixels - Period 1: ${count1}, Period 2: ${count2}`);

  // Determine answer
  if (ndvi2 > ndvi1) {
    console.log(`<answer>A</answer>`);
  } else {
    console.log(`<answer>B</answer>`);
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
